<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/Repositories/Admin/CatalogTagsRepository.php';
$host=(string)getenv('TAGS_QA_DB_HOST');$port=(string)getenv('TAGS_QA_DB_PORT');$name=(string)getenv('TAGS_QA_DB_NAME');$pass=(string)getenv('TAGS_QA_DB_PASS');
if($host!=='127.0.0.1'||$port!=='18998'||$name!=='mi_tags_private_qa_20261023'||strlen($pass)<20)exit(2);
$connect=static fn()=>new PDO("mysql:host=$host;port=$port;dbname=$name;charset=utf8mb4",'root',$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$db=$connect();$meta=$db->query('SELECT @@port p,@@datadir d')->fetch(PDO::FETCH_ASSOC);
$expected=strtolower(str_replace('\\','/',sys_get_temp_dir().'\\mi_tags_private_qa_20261023\\data'));
if((int)$meta['p']!==18998 || rtrim(strtolower(str_replace('\\','/',$meta['d'])),'/')!==rtrim($expected,'/'))exit(3);
$r=new App\Repositories\Admin\CatalogTagsRepository($db);$n=0;
$ok=static function(bool $check,string $label)use(&$n):void{if(!$check)throw new RuntimeException('FAIL '.$label);$n++;echo "PASS $label\n";};
$fail=static function(callable $fn,string $label)use($ok):void{try{$fn();$ok(false,$label);}catch(PDOException|DomainException $e){$ok(true,$label);}};
$db->exec("INSERT INTO categories(id,name,slug,is_active) VALUES(198,'QA category','qa-category-tags',1)");
$db->exec("INSERT INTO products(id,name,slug,category_id,sale_mode,is_active) VALUES(198,'Producto QA','producto-tags-qa',198,'variants',1)");
$db->exec("INSERT INTO product_variants(id,product_id,sku,title,is_active) VALUES(198,198,'QA-TAGS-1','Variante QA',1)");
$g=['name'=>'QA Modalidad','slug'=>'qa-modalidad','sort'=>1,'is_active'=>1];
$group=$r->saveGroup(0,$g);$ok($group>0,'MariaDB group');
$tag=$r->saveTag(0,['group_id'=>$group,'name'=>'QA Spinning','slug'=>'qa-spinning','sort'=>0,'is_active'=>1]);
$ok($tag>0,'MariaDB tag');
$r->syncProductTags(198,[$tag]);$r->syncVariantTags(198,[$tag]);
$ok($r->findProductTagIds(198)===[$tag],'MariaDB product association');
$ok($r->findVariantTagIdsByProduct(198)[198]===[$tag],'MariaDB variant association');
$fail(fn()=>$r->syncProductTags(198,[999999]),'Invalid product tag rejected');
$ok($r->findProductTagIds(198)===[$tag],'Product relation unchanged after invalid');
$fail(fn()=>$r->syncVariantTags(198,[999999]),'Invalid variant tag rejected');
$ok($r->findVariantTagIdsByProduct(198)[198]===[$tag],'Variant relation unchanged after invalid');
$db->beginTransaction();$r->syncProductTags(198,[]);$r->syncVariantTags(198,[]);$ok($r->findProductTagIds(198)===[],'SQL transaction mutation seen');$db->rollBack();
$ok($r->findProductTagIds(198)===[$tag] && $r->findVariantTagIdsByProduct(198)[198]===[$tag],'Real MariaDB rollback restores both');
$fail(fn()=>$r->saveGroup(0,$g),'Physical group UNIQUE duplicate');
$fail(fn()=>$r->saveTag(0,['group_id'=>$group,'name'=>'QA Spinning','slug'=>'qa-spinning','sort'=>0,'is_active'=>1]),'Physical tag UNIQUE duplicate');
$ok((int)$r->listTags()[0]['products_count']===1 && (int)$r->listTags()[0]['variants_count']===1,'Both relation counts');
$matches=$db->query("SELECT COUNT(DISTINCT x.product_id) FROM (SELECT pct.product_id FROM product_catalog_tags pct JOIN catalog_tags t ON t.id=pct.tag_id JOIN catalog_tag_groups g ON g.id=t.group_id WHERE g.slug='qa-modalidad' AND t.slug='qa-spinning' UNION ALL SELECT pv.product_id FROM variant_catalog_tags vt JOIN product_variants pv ON pv.id=vt.variant_id JOIN catalog_tags t ON t.id=vt.tag_id JOIN catalog_tag_groups g ON g.id=t.group_id WHERE g.slug='qa-modalidad' AND t.slug='qa-spinning') x")->fetchColumn();
$ok((int)$matches===1,'Public facet relationship UNION behavior');
$left=$connect();$right=$connect();
$left->beginTransaction();$left->exec("INSERT INTO catalog_tag_groups(name,slug,sort,is_active) VALUES('QA Race','qa-race',0,1)");
$right->exec('SET innodb_lock_wait_timeout=1');
$timedOut=false;
try{$right->exec("INSERT INTO catalog_tag_groups(name,slug,sort,is_active) VALUES('QA Race second','qa-race',0,1)");}catch(PDOException $e){$timedOut=true;}
$ok($timedOut,'Real concurrent UNIQUE lock waiting');
$left->commit();
$fail(fn()=>$right->exec("INSERT INTO catalog_tag_groups(name,slug,sort,is_active) VALUES('QA Race second','qa-race',0,1)"),'Post-commit UNIQUE blocks second writer');
$ok((int)$db->query("SELECT COUNT(*) FROM catalog_tag_groups WHERE slug='qa-race'")->fetchColumn()===1,'One winner, no duplicate');
echo "TAGS_MARIADB_INTEGRITY_PASS $n\n";
